/* =====================================================================
   data.js — ВСЕ тексты и данные учебника.
   Здесь можно спокойно править формулировки, добавлять шаги, термины,
   правила firewall и т.д. Логика (app.js) читает эти объекты как есть.

   Координаты узлов: wide — для широкого экрана, tall — для телефона
   (вертикальная схема). Числа — в единицах viewBox соответствующей сцены.
   ===================================================================== */

