/* =====================================================================
   ЭКРАН «ПУТЬ ЗАПРОСА» (id inside): четыре сценария по общей сети NETWORK
   Шаг: kind — что анимировать:
     start/wrap — запрос собирается на ноутбуке (слои матрёшки растут),
     type — набор адреса в браузере, fork — развилка «знаем IP?»,
     cachedns — проверка кэшей, затем DNS-запрос,
     handshake — служебные сообщения туда-обратно (labels),
     path — пакеты летят по маршруту, на каждом узле видно, что он читает,
     unwrap — сервер снимает слои, back — ответ возвращается (count пакетов),
     render — браузер рисует страницу.
   layers — слои «Анатомии пакета», fields — подписи слоёв (иначе по умолчанию),
   payload — что показать в блоке «в посылке»: {title, lang, code} или {type: 'letter'|'hops'|'unwrap'}.
   В текстах {host}, {vip}, {srcName}, {serverWork}, {back} берутся из сценария.
   ===================================================================== */
